unsigned patch_jump(void *insnbuf, const void *target, unsigned long addr, unsigned len) {
    if (len < 5)
        return len;

    uint32_t *buf = insnbuf;
    const uint32_t *target_addr = target;
    uint32_t delta = (uint32_t)((uintptr_t)target_addr - addr - 5);

    buf[0] = 0xE9; // Opcode for near jump relative
    *(uint32_t *)&buf[1] = delta;

    return 5;
}

unsigned patch_jump_insn(void *insnbuf, const void *target, unsigned long addr, unsigned len) {
    if (len < 5)
        return len;

    /* Set opcode for jump instruction */
    *(unsigned char *)insnbuf = 0xE9;  // x86 relative jump (JMP rel32)

    /* Calculate the offset to the target address */
    long offset = (long)((char *)target - (char *)addr - 5);
    *(long *)((char *)insnbuf + 1) = offset;

    return 5;
}

unsigned patch_jump(void *insnbuf, const void *target, unsigned long addr, unsigned len)
{
    long offset = (long)((char *)target - (char *)addr - 5);
    if (len < 5)
        return len;
    *(unsigned char *)insnbuf = 0xE9; /* jmp rel32 opcode */
    *(long *)((unsigned char *)insnbuf + 1) = offset;
    return 5;
}

unsigned patch_jump_insn(void *insnbuf, const void *target, unsigned long addr, unsigned len) {
    long offset;
    unsigned char *buf = (unsigned char *)insnbuf;

    if (len < 5)
        return len;

    offset = (long)((char *)target - (char *)(addr + 5));
    *(buf++) = 0xE9; /* jmp opcode */
    *(int *)buf = offset;

    return 5;
}

unsigned patch_jump(void *insnbuf, const void *target, unsigned long addr, unsigned len) {
    if (len < 5)
        return len;

    *(uint8_t *)insnbuf = 0xE9; // Opcode for jump
    *(uint32_t *)((uint8_t *)insnbuf + 1) = (uint32_t)((unsigned long)target - (addr + 5));
    return 5;
}
